import React from 'react';
import profileImg from '../assets/profile.jpg'; // Place your photo as src/assets/profile.jpg

export default function Hero() {
  return (
    <section id="home" style={{
      minHeight: '100vh', display: 'flex', alignItems: 'center',
      padding: '80px 5% 0', position: 'relative', overflow: 'hidden'
    }}>
      {/* Background glow */}
      <div style={{
        position: 'absolute', top: -200, right: -100,
        width: 600, height: 600,
        background: 'radial-gradient(circle, rgba(255,107,26,0.08) 0%, transparent 70%)',
        pointerEvents: 'none'
      }} />

      <div style={{
        display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4rem',
        alignItems: 'center', maxWidth: 1100, margin: '0 auto', width: '100%'
      }}>
        {/* LEFT */}
        <div>
          <div style={{
            display: 'inline-flex', alignItems: 'center', gap: '0.5rem',
            background: 'rgba(255,107,26,0.1)', border: '1px solid rgba(255,107,26,0.3)',
            color: 'var(--orange)', fontSize: '0.75rem', letterSpacing: '0.12em',
            textTransform: 'uppercase', padding: '6px 14px', borderRadius: 20, marginBottom: '1.5rem'
          }}>
            <span style={{
              width: 6, height: 6, borderRadius: '50%', background: 'var(--orange)',
              animation: 'pulse 2s infinite', display: 'inline-block'
            }} />
            Available for Remote Work
          </div>

          <h1 style={{
            fontSize: 'clamp(2.5rem, 5vw, 4rem)', fontWeight: 800,
            lineHeight: 1.0, letterSpacing: '-0.03em', marginBottom: '1rem'
          }}>
            Bisrat<br />
            <span style={{ color: 'var(--orange)' }}>Amare</span>
          </h1>

          <p style={{
            fontFamily: "'Space Mono', monospace", color: 'var(--muted)',
            fontSize: '0.85rem', marginBottom: '2rem', lineHeight: 1.8
          }}>
            <span style={{ color: 'var(--orange)' }}>Full-Stack Software Engineer</span><br />
            React · Node.js · Flutter · Healthcare Tech<br />
            Building enterprise-grade digital systems.
          </p>

          <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
            <a href="#projects" className="btn-primary">View Work ↓</a>
            <a href="/Bisrat_Amare_CV.pdf" download className="btn-outline">Download CV ↓</a>
            <a href="#contact" className="btn-outline">Get In Touch</a>
          </div>

          {/* Stats */}
          <div style={{ display: 'flex', gap: '2rem', marginTop: '2.5rem' }}>
            {[
              { num: '5+', label: 'Years Exp.' },
              { num: '20+', label: 'Projects' },
              { num: '13+', label: 'Technologies' }
            ].map(s => (
              <div key={s.label}>
                <div style={{ fontSize: '1.8rem', fontWeight: 800, color: 'var(--orange)', lineHeight: 1 }}>{s.num}</div>
                <div style={{ fontSize: '0.7rem', color: 'var(--muted)', letterSpacing: '0.1em', textTransform: 'uppercase', marginTop: 4 }}>{s.label}</div>
              </div>
            ))}
          </div>
        </div>

        {/* RIGHT — Profile Image (responsive, cropped, premium avatar) */}
        <div className="hero-profile" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', position: 'relative' }}>
          <div className="profile-glow" aria-hidden />
          <div className="profile-outer">
            <div className="profile-inner">
              <img
                src={profileImg}
                alt="Bisrat Amare"
                className="profile-img"
              />
            </div>
          </div>
        </div>
      </div>

      <style>{`
        :root{ --avatar-size: clamp(160px, 28vw, 360px); }

        /* Avatar layout */
        .hero-profile .profile-glow{
          position:absolute; top:-20px; right:-20px; z-index:0;
          width: calc(var(--avatar-size) + 80px); height: calc(var(--avatar-size) + 80px);
          border-radius:50%;
          background: radial-gradient(circle, rgba(255,107,26,0.18), transparent 40%);
          filter: blur(18px);
          pointer-events:none;
        }

        .profile-outer{
          width: var(--avatar-size); height: var(--avatar-size); border-radius:50%; padding:8px;
          background: linear-gradient(135deg,#FF6B1A,#ff3c00,#FF6B1A);
          box-shadow: 0 10px 30px rgba(255,107,26,0.18), 0 4px 18px rgba(0,0,0,0.25);
          position:relative; z-index:2; display:flex; align-items:center; justify-content:center;
        }

        .profile-inner{
          width:100%; height:100%; border-radius:50%; overflow:hidden; display:block;
          background: #0A0A0A; border: 3px solid rgba(10,10,10,0.6);
        }

        .profile-img{
          width:100%; height:100%; object-fit: cover; object-position: 50% 36%; display:block;
          filter: contrast(1.05) saturate(1.08); transition: transform .25s ease; image-rendering: auto;
        }

        .profile-outer:hover .profile-img{ transform: scale(1.02); }

        /* Smaller screens adjustments */
        @media (max-width: 900px) {
          :root{ --avatar-size: clamp(140px, 30vw, 300px); }
          .profile-img{ object-position: 50% 40%; }
          .hero-profile .profile-glow{ top:-10px; right:-10px; }
        }

        @media (max-width: 480px) {
          :root{ --avatar-size: clamp(110px, 36vw, 200px); }
          .profile-img{ object-position: 50% 44%; }
        }

        @keyframes pulse { 0%,100%{opacity:1} 50%{opacity:0.3} }
        @keyframes rotateSlow { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }
      `}</style>
    </section>
  );
}
